def _write_request(out, v, depth):
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "op")
    out += b": "
    _esc(out, v.op)
    if v.name:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "name")
        out += b": "
        _esc(out, v.name)
    if v.rights:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "rights")
        out += b": "
        _strs(out, v.rights, depth + 1)
    if v.secret:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "secret")
        out += b": "
        _esc(out, v.secret)
    if v.token:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "token")
        out += b": "
        _esc(out, v.token)
    if v.right:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "right")
        out += b": "
        _esc(out, v.right)
    if v.why:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "why")
        out += b": "
        _esc(out, v.why)
    if v.app:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "app")
        out += b": "
        _esc(out, v.app)
    if v.admin:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "admin")
        out += b": "
        _esc(out, v.admin)
    out += b"\n"
    _pad(out, depth)
    out += b"}"


