def _write_response_metadata(out, v, depth):
    out += b"{"
    first = True
    if v.code:
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "code")
        out += b": "
        _esc(out, v.code)
    if v.error:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "error")
        out += b": "
        _esc(out, v.error)
    if v.secret:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "secret")
        out += b": "
        _esc(out, v.secret)
    if v.token:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "token")
        out += b": "
        _esc(out, v.token)
    if v.expires:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "expires")
        out += b": "
        _esc(out, v.expires)
    if v.app is not None:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "app")
        out += b": "
        _write_app_metadata(out, v.app, depth + 1)
    if v.right:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "right")
        out += b": "
        _esc(out, v.right)
    if v.apps:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "apps")
        out += b": "
        _write_list(out, v.apps, depth + 1, _write_app_metadata)
    if v.holds:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "holds")
        out += b": "
        _write_list(out, v.holds, depth + 1, _write_hold_metadata)
    if not first:
        out += b"\n"
        _pad(out, depth)
    out += b"}"


